package hyperv

// Unattended-install answer files ("seeds") for each guest OS. Everything is
// generated per VM (user, password, SSH keys, host key) and written onto a
// small ISO that is attached as a second DVD drive:
//
//   ubuntu-24.04       NoCloud CIDATA: user-data (autoinstall) + meta-data
//   windows-11         autounattend.xml + agentos-setup.ps1 (+ OpenSSH / TightVNC MSIs)
//   fedora-workstation OEMDRV: ks.cfg (Anaconda loads it automatically)

import (
	"bytes"
	"crypto/ed25519"
	"crypto/rand"
	"encoding/base64"
	"encoding/pem"
	"fmt"
	"strings"
	"text/template"

	"golang.org/x/crypto/ssh"
)

// SeedParams are the per-VM values baked into a seed.
type SeedParams struct {
	Hostname      string
	User          string
	Password      string
	PasswordHash  string // sha512-crypt of Password (Linux)
	AuthorizedKey string // "ssh-ed25519 AAAA... agentos"
	HostKeyPriv   string // OpenSSH PEM ed25519 host key (Linux)
	HostKeyPub    string
	Locale        string // zh_CN.UTF-8 | en_US.UTF-8
	WinLocale     string // zh-CN | en-US
	TimeZone      string // Asia/Shanghai
	WinTimeZone   string // China Standard Time
	VNCPort       int
	FedoraRel     int
	Proxy         string // optional http proxy for package downloads during install
}

// newSSHKeyPair returns an OpenSSH PEM private key and authorized_keys line.
func newSSHKeyPair(comment string) (priv, pub, fingerprint string, err error) {
	pk, sk, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return "", "", "", err
	}
	blk, err := ssh.MarshalPrivateKey(sk, comment)
	if err != nil {
		return "", "", "", err
	}
	spk, err := ssh.NewPublicKey(pk)
	if err != nil {
		return "", "", "", err
	}
	pub = strings.TrimSpace(string(ssh.MarshalAuthorizedKey(spk)))
	if comment != "" {
		pub += " " + comment
	}
	return string(pem.EncodeToMemory(blk)), pub, ssh.FingerprintSHA256(spk), nil
}

func b64(s string) string { return base64.StdEncoding.EncodeToString([]byte(s)) }

func render(name, tmpl string, data any) ([]byte, error) {
	t, err := template.New(name).Funcs(template.FuncMap{"b64": b64, "xml": xmlEscape, "yq": yamlQuote}).Parse(tmpl)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func xmlEscape(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;", "'", "&apos;")
	return r.Replace(s)
}

func yamlQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", "''") + "'" }

// ---------------- Ubuntu 24.04 Desktop (autoinstall) ----------------

// ubuntuSetupScript runs inside the installed system (curtin in-target) at the
// end of the install: desktop autologin on Xorg, x11vnc (localhost only, reached
// through the SSH tunnel), Hyper-V KVP daemon (guest IP), Chinese fonts/IME,
// no screen lock, passwordless sudo, pinned SSH host key.
const ubuntuSetupScript = `#!/bin/bash
exec >>/var/log/agentos-setup.log 2>&1
set -x
U={{.User}}
export DEBIAN_FRONTEND=noninteractive
# SSH host key generated by AgentOS (fingerprint pinned on the host)
rm -f /etc/ssh/ssh_host_ed25519_key /etc/ssh/ssh_host_ed25519_key.pub
echo '{{b64 .HostKeyPriv}}' | base64 -d > /etc/ssh/ssh_host_ed25519_key
echo '{{b64 .HostKeyPub}}' | base64 -d > /etc/ssh/ssh_host_ed25519_key.pub
chmod 600 /etc/ssh/ssh_host_ed25519_key; chmod 644 /etc/ssh/ssh_host_ed25519_key.pub
mkdir -p /home/$U/.ssh
echo '{{b64 .AuthorizedKey}}' | base64 -d >> /home/$U/.ssh/authorized_keys
chmod 700 /home/$U/.ssh; chmod 600 /home/$U/.ssh/authorized_keys
chown -R $U:$U /home/$U/.ssh
systemctl enable ssh || true
echo "$U ALL=(ALL) NOPASSWD:ALL" > /etc/sudoers.d/90-agentos; chmod 440 /etc/sudoers.d/90-agentos
# GDM: automatic login into an Xorg session (x11vnc needs X11)
mkdir -p /etc/gdm3
cat > /etc/gdm3/custom.conf <<EOC
[daemon]
AutomaticLoginEnable=true
AutomaticLogin=$U
WaylandEnable=false
EOC
# GNOME defaults: never lock / blank / suspend
mkdir -p /etc/dconf/profile /etc/dconf/db/local.d
printf 'user-db:user\nsystem-db:local\n' > /etc/dconf/profile/user
cat > /etc/dconf/db/local.d/00-agentos <<'EOC'
[org/gnome/desktop/screensaver]
lock-enabled=false
idle-activation-enabled=false
ubuntu-lock-on-suspend=false
[org/gnome/desktop/session]
idle-delay=uint32 0
[org/gnome/settings-daemon/plugins/power]
sleep-inactive-ac-type='nothing'
sleep-inactive-battery-type='nothing'
idle-dim=false
[org/gnome/desktop/lockdown]
disable-lock-screen=true
[org/gnome/shell]
welcome-dialog-last-shown-version='999'
EOC
# input method: pinyin next to the default layout
cat >> /etc/dconf/db/local.d/00-agentos <<'EOC'
[org/gnome/desktop/input-sources]
sources=[('xkb', 'us'), ('ibus', 'libpinyin')]
EOC
dconf update || true
# Hyper-V console resolution 1920x1080
if [ -f /etc/default/grub ]; then
  sed -i 's/^GRUB_CMDLINE_LINUX_DEFAULT=.*/GRUB_CMDLINE_LINUX_DEFAULT="quiet splash video=Virtual-1:1920x1080"/' /etc/default/grub
  update-grub || true
fi
# time zone + language (the desktop installer may ignore them, e.g. offline)
ln -sf /usr/share/zoneinfo/{{.TimeZone}} /etc/localtime; echo '{{.TimeZone}}' > /etc/timezone
grep -q '^{{.Locale}}' /etc/locale.gen 2>/dev/null || echo '{{.Locale}} UTF-8' >> /etc/locale.gen
locale-gen {{.Locale}} || true
update-locale LANG={{.Locale}} || printf 'LANG={{.Locale}}\n' > /etc/default/locale
mkdir -p /var/lib/AccountsService/users
printf '[User]\nLanguage={{.Locale}}\nSession=ubuntu-xorg\nSystemAccount=false\n' > /var/lib/AccountsService/users/$U
# no "new Ubuntu release available" pop-ups on the agent desktop
[ -f /etc/update-manager/release-upgrades ] && sed -i 's/^Prompt=.*/Prompt=never/' /etc/update-manager/release-upgrades
# skip the first-login welcome wizard
apt-get -y purge gnome-initial-setup || true
mkdir -p /home/$U/.config; echo yes > /home/$U/.config/gnome-initial-setup-done; chown -R $U:$U /home/$U/.config
cat > /usr/local/bin/agentos-vnc <<'EOC'
#!/bin/sh
# AgentOS desktop tab: share the logged-in X session on guest loopback only
while true; do
  x11vnc -display "${DISPLAY:-:0}" -localhost -rfbport {{.VNCPort}} -forever -shared -nopw -noxdamage -repeat -quiet -o /tmp/agentos-x11vnc.log
  sleep 2
done
EOC
chmod 755 /usr/local/bin/agentos-vnc
cat > /etc/xdg/autostart/agentos-x11vnc.desktop <<'EOC'
[Desktop Entry]
Type=Application
Name=AgentOS VNC
Exec=/usr/local/bin/agentos-vnc
X-GNOME-Autostart-enabled=true
NoDisplay=true
EOC
{{if .Proxy}}echo 'Acquire::http::Proxy "{{.Proxy}}"; Acquire::https::Proxy "{{.Proxy}}";' > /etc/apt/apt.conf.d/90agentos-proxy
{{end}}# Packages that need the network (VNC, Hyper-V KVP, Chinese fonts/IME): tried now,
# and retried on every boot by agentos-packages.service until they are in place
# (the install itself falls back to offline mode when no mirror is reachable).
cat > /usr/local/sbin/agentos-packages <<'EOC'
#!/bin/bash
set -x
export DEBIAN_FRONTEND=noninteractive
[ -f /var/lib/agentos/packages-done ] && exit 0
apt-get update || exit 1
apt-get install -y openssh-server || exit 1
systemctl enable --now ssh 2>/dev/null || systemctl enable ssh || true
K=$(uname -r); [ -d /lib/modules/$K ] || K=$(ls /lib/modules | sort -V | tail -1)
apt-get install -y x11vnc || exit 1
apt-get install -y "linux-cloud-tools-$K" linux-cloud-tools-common || apt-get install -y linux-cloud-tools-virtual || true
systemctl enable --now hv-kvp-daemon.service 2>/dev/null || true
apt-get install -y fonts-noto-cjk ibus-libpinyin language-pack-zh-hans language-pack-gnome-zh-hans || true
mkdir -p /var/lib/agentos; date -Is > /var/lib/agentos/packages-done
systemctl disable agentos-packages.service 2>/dev/null || true
EOC
chmod 755 /usr/local/sbin/agentos-packages
cat > /etc/systemd/system/agentos-packages.service <<'EOC'
[Unit]
Description=AgentOS: install desktop sharing / guest tools when the network is up
Wants=network-online.target
After=network-online.target
[Service]
Type=oneshot
ExecStart=/usr/local/sbin/agentos-packages
Restart=on-failure
RestartSec=60
StandardOutput=append:/var/log/agentos-packages.log
StandardError=append:/var/log/agentos-packages.log
[Install]
WantedBy=multi-user.target
EOC
systemctl enable agentos-packages.service || ln -sf /etc/systemd/system/agentos-packages.service /etc/systemd/system/multi-user.target.wants/agentos-packages.service
timeout 1200 /usr/local/sbin/agentos-packages >> /var/log/agentos-packages.log 2>&1 || true
# cloud-init must not re-run against the seed disk on first boot
mkdir -p /etc/cloud; touch /etc/cloud/cloud-init.disabled
mkdir -p /var/lib/agentos; date -Is > /var/lib/agentos/installed
exit 0
`

const ubuntuUserData = `#cloud-config
autoinstall:
  version: 1
  interactive-sections: []
  locale: {{.Locale}}
  keyboard:
    layout: us
  timezone: {{.TimeZone}}
  identity:
    realname: AgentOS
    hostname: {{.Hostname}}
    username: {{.User}}
    password: {{yq .PasswordHash}}
  ssh:
    # openssh-server is not on the desktop ISO: installing it from the
    # installer would abort an offline install, so the setup script installs
    # it (and retries on every boot until the network works).
    install-server: false
    allow-pw: true
    authorized-keys:
      - {{yq .AuthorizedKey}}
  storage:
    layout:
      name: direct
  codecs:
    install: false
  drivers:
    install: false
  updates: security
  apt:
    geoip: false
    fallback: offline-install
{{- if .Proxy}}
  proxy: {{yq .Proxy}}
{{- end}}
  late-commands:
    - echo '{{.SetupB64}}' | base64 -d > /target/root/agentos-setup.sh
    - curtin in-target --target=/target -- bash /root/agentos-setup.sh || chroot /target bash /root/agentos-setup.sh || true
  shutdown: reboot
`

// UbuntuSeed returns the CIDATA files.
func UbuntuSeed(p SeedParams, instanceID string) ([]SeedFile, error) {
	script, err := render("setup", ubuntuSetupScript, p)
	if err != nil {
		return nil, err
	}
	ud, err := render("user-data", ubuntuUserData, struct {
		SeedParams
		SetupB64 string
	}{p, base64.StdEncoding.EncodeToString(script)})
	if err != nil {
		return nil, err
	}
	md := fmt.Sprintf("instance-id: %s\nlocal-hostname: %s\n", instanceID, p.Hostname)
	return []SeedFile{{Name: "user-data", Data: ud}, {Name: "meta-data", Data: []byte(md)}}, nil
}

// UbuntuAutoinstallAppend is the kernel cmdline for Ubuntu Desktop zero-touch
// install. Bare ds=nocloud (NO semicolon / s= path) selects DataSourceNoCloud.
// After casper pivot, /agentos-seed/ from the initrd overlay is gone; the
// casper-bottom hook copies user-data into /var/lib/cloud/seed/nocloud/ which
// bare ds=nocloud consumes. ds=nocloud;s=/agentos-seed/ regresses to a live
// session (empty disk). Semicolon is also forbidden for GRUB typing.
const UbuntuAutoinstallAppend = `autoinstall ds=nocloud noprompt splash console=ttyS0,115200n8 earlyprintk=ttyS0 loglevel=7 ---`

// UbuntuGrubCommands are typed at the GRUB prompt of the desktop ISO (Hyper-V
// Msvm_Keyboard path). QEMU prefers -kernel/-append via UbuntuAutoinstallAppend
// instead of racing Esc/c at the GRUB menu.
func UbuntuGrubCommands(kernel, initrd string) []string {
	return []string{
		"linux " + kernel + " " + UbuntuAutoinstallAppend,
		"initrd " + initrd,
		"boot",
	}
}

