// windowsSetupPS runs at first logon (elevated): OpenSSH server with the
// AgentOS key, TightVNC (loopback only, reached through the SSH tunnel),
// RDP on, no lock screen / sleep, ready marker.
//
// OpenSSH is offline-first: install the MSI shipped on the seed ISO before any
// Get/Add-WindowsCapability -Online call. -Online can hang indefinitely when the
// guest has no Internet (common under QEMU user-net / restricted Hyper-V), which
// previously blocked MSI fallback and left desktop-up / SSH-down forever.
const windowsSetupPS = `$ErrorActionPreference = 'Continue'
$src = Split-Path -Parent $MyInvocation.MyCommand.Path
$state = 'C:\ProgramData\AgentOS'
New-Item -ItemType Directory -Force $state | Out-Null
Start-Transcript -Path "$state\setup.log" -Append | Out-Null
function Step($m) { Write-Output ("[{0}] {1}" -f (Get-Date -Format s), $m) }

Step 'network profile -> private'
Get-NetConnectionProfile -ErrorAction SilentlyContinue | Set-NetConnectionProfile -NetworkCategory Private -ErrorAction SilentlyContinue

Step 'power / lock screen'
powercfg /change monitor-timeout-ac 0
powercfg /change standby-timeout-ac 0
powercfg /change hibernate-timeout-ac 0
New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Personalization' -Force | Out-Null
Set-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Personalization' -Name NoLockScreen -Value 1 -Type DWord
New-Item -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement' -Force | Out-Null
Set-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement' -Name ScoobeSystemSettingEnabled -Value 0 -Type DWord
reg add "HKCU\Control Panel\Desktop" /v ScreenSaveActive /t REG_SZ /d 0 /f | Out-Null

Step 'remote desktop'
Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Terminal Server' -Name fDenyTSConnections -Value 0
Enable-NetFirewallRule -Group '@FirewallAPI.dll,-28752' -ErrorAction SilentlyContinue

Step 'OpenSSH server (offline-first)'
$ok = $false
if (Test-Path "$src\OpenSSH-Win64.msi") {
  Step 'installing OpenSSH from MSI'
  $p = Start-Process msiexec.exe -Wait -PassThru -ArgumentList '/i', "$src\OpenSSH-Win64.msi", '/qn', '/norestart'
  Step ("msiexec OpenSSH exit=$($p.ExitCode)")
  $ok = [bool](Get-Service sshd -ErrorAction SilentlyContinue)
} else {
  Step 'OpenSSH-Win64.msi missing next to setup script'
}
if (-not $ok) {
  Step 'MSI missing/failed; Online capability with 90s timeout (may fail offline)'
  try {
    $job = Start-Job {
      $cap = Get-WindowsCapability -Online -Name 'OpenSSH.Server*' -ErrorAction Stop | Select-Object -First 1
      if ($cap -and $cap.State -ne 'Installed') {
        Add-WindowsCapability -Online -Name $cap.Name | Out-Null
      }
    }
    if (Wait-Job $job -Timeout 90) {
      Receive-Job $job | Out-String | Write-Output
    } else {
      Step 'Online capability timed out (90s)'
      Stop-Job $job -ErrorAction SilentlyContinue
      Remove-Job $job -Force -ErrorAction SilentlyContinue
    }
  } catch { Step "capability: $_" }
  $ok = [bool](Get-Service sshd -ErrorAction SilentlyContinue)
}
$ak = 'C:\ProgramData\ssh\administrators_authorized_keys'
New-Item -ItemType Directory -Force 'C:\ProgramData\ssh' | Out-Null
Set-Content -Path $ak -Value '{{.AuthorizedKey}}' -Encoding ascii
icacls $ak /inheritance:r /grant '*S-1-5-32-544:F' /grant '*S-1-5-18:F' | Out-Null
Set-Service sshd -StartupType Automatic -ErrorAction SilentlyContinue
Start-Service sshd -ErrorAction SilentlyContinue
if (-not (Get-NetFirewallRule -Name 'OpenSSH-Server-In-TCP' -ErrorAction SilentlyContinue)) {
  New-NetFirewallRule -Name 'OpenSSH-Server-In-TCP' -DisplayName 'OpenSSH Server (sshd)' -Enabled True -Direction Inbound -Protocol TCP -Action Allow -LocalPort 22 | Out-Null
}
$sshRunning = [bool](Get-Service sshd -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' })
if ($sshRunning) { Step 'sshd running' } else { Step 'WARNING sshd not running after install attempts' }

Step 'TightVNC (loopback only)'
if (Test-Path "$src\tightvnc-setup-64bit.msi") {
  Start-Process msiexec.exe -Wait -ArgumentList '/i', "$src\tightvnc-setup-64bit.msi", '/quiet', '/norestart', 'ADDLOCAL=Server',
    'SET_USEVNCAUTHENTICATION=1', 'VALUE_OF_USEVNCAUTHENTICATION=0', 'SET_ALLOWLOOPBACK=1', 'VALUE_OF_ALLOWLOOPBACK=1',
    'SET_LOOPBACKONLY=1', 'VALUE_OF_LOOPBACKONLY=1', 'SET_RFBPORT=1', 'VALUE_OF_RFBPORT={{.VNCPort}}',
    'SET_REMOVEWALLPAPER=1', 'VALUE_OF_REMOVEWALLPAPER=0', 'SET_RUNCONTROLINTERFACE=1', 'VALUE_OF_RUNCONTROLINTERFACE=0'
  Set-Service tvnserver -StartupType Automatic -ErrorAction SilentlyContinue
  Restart-Service tvnserver -ErrorAction SilentlyContinue
}

# Always write ready.txt once first-logon setup finishes (desktop is up), even if
# sshd failed — Hyper-V guest-agent / humans can still see the marker + setup.log.
$sshState = if ($sshRunning) { 'ssh=running' } else { 'ssh=FAIL' }
Step "done $sshState"
@"
$sshState
$(Get-Date -Format o)
"@ | Set-Content "$state\ready.txt" -Encoding ascii
if (-not $sshRunning) {
  Step 'ready.txt written with ssh=FAIL — E2E SSH polls will keep failing until OpenSSH is fixed'
}
Stop-Transcript | Out-Null
`

// WinComputerName makes a valid Windows ComputerName: at most 15 characters
// (NetBIOS), letters/digits/hyphen. A longer name makes Windows Setup fail
// the specialize pass with "计算机意外地重新启动或遇到错误".
func WinComputerName(h string) string {
	var b strings.Builder
	for _, r := range h {
		if r < 128 && (r == '-' || r >= '0' && r <= '9' || r >= 'A' && r <= 'Z' || r >= 'a' && r <= 'z') {
			b.WriteRune(r)
		}
	}
	n := b.String()
	if len(n) > 15 {
		n = n[:15]
	}
	n = strings.Trim(n, "-")
	if n == "" || strings.Trim(n, "0123456789") == "" {
		n = "AGENTOS-PC"
	}
	return n
}

// WindowsSeed returns the autounattend files; extra are optional installers
// (OpenSSH-Win64.msi, tightvnc-setup-64bit.msi) placed next to the script.
func WindowsSeed(p SeedParams, extra []SeedFile) ([]SeedFile, error) {
	input := "0409:00000409"
	if strings.HasPrefix(strings.ToLower(p.WinLocale), "zh") {
		input = "0804:{81D4E9C9-1D3B-41BC-9E6C-4B40BF79E35E}{FA550B04-5AD7-411f-A5AC-CA038EC515D7}"
	}
	xml, err := render("unattend", windowsUnattend, struct {
		SeedParams
		InputLocale string
		WinName     string
	}{p, input, WinComputerName(p.Hostname)})
	if err != nil {
		return nil, err
	}
	ps, err := render("setup", windowsSetupPS, p)
	if err != nil {
		return nil, err
	}
	// PowerShell 5.1 reads BOM-less scripts as ANSI; keep it ASCII + BOM.
	ps = append([]byte{0xEF, 0xBB, 0xBF}, ps...)
	files := []SeedFile{{Name: "autounattend.xml", Data: xml}, {Name: "agentos-setup.ps1", Data: ps}}
	return append(files, extra...), nil
}

// ---------------- Fedora Workstation (kickstart) ----------------

const fedoraKickstart = `# AgentOS unattended Fedora Workstation (GNOME on Xorg + x11vnc)
text
lang {{.Locale}}
keyboard us
timezone {{.TimeZone}} --utc
network --bootproto=dhcp --activate --hostname={{.Hostname}}
url --mirrorlist=https://mirrors.fedoraproject.org/mirrorlist?repo=fedora-{{.FedoraRel}}&arch=x86_64{{if .Proxy}} --proxy={{.Proxy}}{{end}}
repo --name=updates --mirrorlist=https://mirrors.fedoraproject.org/mirrorlist?repo=updates-released-f{{.FedoraRel}}&arch=x86_64{{if .Proxy}} --proxy={{.Proxy}}{{end}}
zerombr
clearpart --all --initlabel --disklabel=gpt
autopart
bootloader --append="video=Virtual-1:1920x1080"
rootpw --lock
user --name={{.User}} --groups=wheel --password={{.PasswordHash}} --iscrypted --gecos="AgentOS"
sshkey --username={{.User}} "{{.AuthorizedKey}}"
services --enabled=sshd,hypervkvpd,hypervvssd
firstboot --disable
xconfig --startxonboot
reboot

%packages
@^workstation-product-environment
hyperv-daemons
openssh-server
x11vnc
ibus-libpinyin
-gnome-initial-setup
%end

%post --log=/root/agentos-post.log
echo '{{b64 .HostKeyPriv}}' | base64 -d > /etc/ssh/ssh_host_ed25519_key
echo '{{b64 .HostKeyPub}}' | base64 -d > /etc/ssh/ssh_host_ed25519_key.pub
chmod 600 /etc/ssh/ssh_host_ed25519_key; chmod 644 /etc/ssh/ssh_host_ed25519_key.pub
restorecon -R /etc/ssh || true
echo "{{.User}} ALL=(ALL) NOPASSWD:ALL" > /etc/sudoers.d/90-agentos; chmod 440 /etc/sudoers.d/90-agentos
# GDM: automatic login into an Xorg session (x11vnc needs X11; do not leave Wayland-only)
mkdir -p /etc/gdm
cat > /etc/gdm/custom.conf <<EOC
[daemon]
AutomaticLoginEnable=True
AutomaticLogin={{.User}}
WaylandEnable=false
EOC
mkdir -p /var/lib/AccountsService/users
printf '[User]\nLanguage={{.Locale}}\nSession=gnome-xorg\nSystemAccount=false\n' > /var/lib/AccountsService/users/{{.User}}
mkdir -p /etc/dconf/db/local.d /etc/dconf/profile
printf 'user-db:user\nsystem-db:local\n' > /etc/dconf/profile/user
cat > /etc/dconf/db/local.d/00-agentos <<'EOC'
[org/gnome/desktop/screensaver]
lock-enabled=false
idle-activation-enabled=false
[org/gnome/desktop/session]
idle-delay=uint32 0
[org/gnome/settings-daemon/plugins/power]
sleep-inactive-ac-type='nothing'
sleep-inactive-battery-type='nothing'
idle-dim=false
[org/gnome/desktop/lockdown]
disable-lock-screen=true
[org/gnome/shell]
welcome-dialog-last-shown-version='999'
[org/gnome/desktop/input-sources]
sources=[('xkb', 'us'), ('ibus', 'libpinyin')]
EOC
dconf update || true
# AgentOS desktop tab: share the logged-in X session on guest loopback only
cat > /usr/local/bin/agentos-vnc <<'EOC'
#!/bin/sh
while true; do
  x11vnc -display "${DISPLAY:-:0}" -localhost -rfbport {{.VNCPort}} -forever -shared -nopw -noxdamage -repeat -quiet -o /tmp/agentos-x11vnc.log
  sleep 2
done
EOC
chmod 755 /usr/local/bin/agentos-vnc
mkdir -p /etc/xdg/autostart
cat > /etc/xdg/autostart/agentos-x11vnc.desktop <<'EOC'
[Desktop Entry]
Type=Application
Name=AgentOS VNC
Exec=/usr/local/bin/agentos-vnc
X-GNOME-Autostart-enabled=true
NoDisplay=true
EOC
mkdir -p /home/{{.User}}/.config; echo yes > /home/{{.User}}/.config/gnome-initial-setup-done
chown -R {{.User}}:{{.User}} /home/{{.User}}/.config || true
dnf install -y google-noto-sans-cjk-ttc-fonts google-noto-sans-cjk-fonts || true
systemctl set-default graphical.target
mkdir -p /var/lib/agentos; date -Is > /var/lib/agentos/installed
%end
`

// FedoraSeed returns the OEMDRV kickstart.
func FedoraSeed(p SeedParams) ([]SeedFile, error) {
	ks, err := render("ks", fedoraKickstart, p)
	if err != nil {
		return nil, err
	}
	return []SeedFile{{Name: "ks.cfg", Data: ks}}, nil
}
